import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import { CloudRain, AlertTriangle, CheckCircle, Activity } from "lucide-react";
import "./RiverDashboard.css";

/* ================= CONFIG ================= */

// Ensure this matches your Django running port
const PRESIGN_ENDPOINT = "http://127.0.0.1:8000/api/weather/s3-presign";

/* ================= COMPONENT ================= */

const RiverDashboard = () => {
  const [forecastData, setForecastData] = useState([]);
  const [analysisData, setAnalysisData] = useState("");
  const [loading, setLoading] = useState(true);

  /* ================= CSV PARSER (ROBUST VERSION) ================= */
  const parseCSV = (csvText) => {
    if (!csvText) return [];
    
    const lines = csvText.trim().split("\n");
    if (lines.length < 2) return []; // Need at least headers + 1 row

    // Normalize headers: remove quotes, trim spaces, make lowercase for matching
    const headers = lines[0].split(",").map(h => h.trim().replace(/"/g, "").toLowerCase());
    
    // Find indices safely (handling case mismatch)
    // Looks for 'timestamp' or 'date'
    const timeIndex = headers.findIndex(h => h.includes("timestamp") || h.includes("date"));
    // Looks for 'predicted' or 'level'
    const levelIndex = headers.findIndex(h => h.includes("predicted") || h.includes("level"));

    if (timeIndex === -1 || levelIndex === -1) {
      console.error("CSV Headers mismatch. Found:", headers);
      return [];
    }

    return lines.slice(1)
      .map(line => {
        const values = line.split(",");
        // Safety check: ensure line has enough columns
        if (values.length <= Math.max(timeIndex, levelIndex)) return null;

        const rawTime = values[timeIndex]?.trim();
        const rawLevel = values[levelIndex]?.trim();

        if (!rawTime || !rawLevel) return null;

        // Clean formatting: Extract time "HH:MM" from "YYYY-MM-DD HH:MM:SS"
        // If rawTime is just "15:00", use it directly. If it has a space, split it.
        const timeDisplay = rawTime.includes(" ") ? rawTime.split(" ")[1].slice(0, 5) : rawTime;

        return {
          time: timeDisplay,
          level: parseFloat(rawLevel),
        };
      })
      .filter(item => item && !isNaN(item.level)); // Filter out nulls and invalid numbers
  };

  /* ================= FETCH DATA ================= */
  const fetchForecast = async () => {
    try {
      // Step 1: Get the Presigned URL from Backend
      const presign = await axios.get(PRESIGN_ENDPOINT, {
        params: { file: "forecast_output.csv" },
      });

      if (!presign || !presign.data || !presign.data.url) {
        console.error('Presign failed or returned no url for forecast:', presign && presign.data);
        return;
      }

      // Step 2: Download the file directly from S3
      const fileResponse = await axios.get(presign.data.url, {
        responseType: "text",
      });

      const parsed = parseCSV(fileResponse.data);
      setForecastData(parsed);

    } catch (error) {
      console.error("Forecast fetch failed:", error);
    }
  };

  const fetchCausality = async () => {
    try {
      // Step 1: Get the Presigned URL for the text file
      const presign = await axios.get(PRESIGN_ENDPOINT, {
        params: { file: "lime_sentences_manual.txt" },
      });

      if (!presign || !presign.data || !presign.data.url) {
        console.error('Presign failed or returned no url for causality:', presign && presign.data);
        return;
      }

      // Step 2: Download the file directly from S3
      const fileResponse = await axios.get(presign.data.url, {
        responseType: "text",
      });

      setAnalysisData(fileResponse.data);

    } catch (error) {
      console.error("Causality fetch failed:", error);
    }
  };

  /* ================= LOAD ON START ================= */
  useEffect(() => {
    Promise.all([fetchForecast(), fetchCausality()])
      .finally(() => setLoading(false));
  }, []);

  /* ================= UI ================= */
  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>River Water Level Dashboard</h1>
        <div className="status-indicator online">
          <CheckCircle size={16} />
          <span>Live feed</span>
        </div>
      </header>

      <div className="main-content">
        {/* ===== CHART ===== */}
        <div className="chart-section">
          <div className="section-header">
            <Activity className="icon" />
            <h2>Water Level Forecast</h2>
          </div>

          {forecastData.length > 0 ? (
            <div className="chart-container">
              <ResponsiveContainer width="100%" height={300}>
                <AreaChart data={forecastData}>
                  <defs>
                    <linearGradient id="colorLevel" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#0ea5e9" stopOpacity={0.8} />
                      <stop offset="95%" stopColor="#0ea5e9" stopOpacity={0} />
                    </linearGradient>
                  </defs>

                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="time" />
                  <YAxis />
                  <Tooltip />

                  <Area
                    type="monotone"
                    dataKey="level"
                    stroke="#0ea5e9"
                    fill="url(#colorLevel)"
                    name="Predicted Water Level"
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <p>{loading ? "Loading forecast..." : "No forecast data available."}</p>
          )}
        </div>

        {/* ===== AI ANALYSIS ===== */}
        <div className="analysis-section">
          <div className="section-header">
            <CloudRain className="icon" />
            <h2>AI Causality Analysis</h2>
          </div>

          {analysisData ? (
            <ul>
              {analysisData.split("\n").map((line, i) =>
                line.trim() && <li key={i}>{line}</li>
              )}
            </ul>
          ) : (
            <p>{loading ? "Loading analysis..." : "No analysis available."}</p>
          )}
        </div>
      </div>

      <footer className="dashboard-footer">
        <AlertTriangle size={16} />
        <p>
          DISCLAIMER: AI-based predictions. Always follow official flood alerts.
        </p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
